-- Sheet 2 staffing analysis layout: frameworks and notes are editable; actual counts are calculated from personnel.
begin;
create table if not exists public.manpower_analysis_rows (
 id uuid primary key default gen_random_uuid(),
 source_period text not null default '2569-11',
 sort_order integer not null,
 row_no text not null default '',
 row_type text not null check (row_type in ('group','unit','role','practitioner')),
 group_name text not null,
 label text not null,
 scope_unit text,
 scope_type text not null check (scope_type in ('group','unit','hospital')),
 staff_role text,
 quota_nurse integer check (quota_nurse is null or quota_nurse >= 0),
 quota_helper integer check (quota_helper is null or quota_helper >= 0),
 quota_building integer check (quota_building is null or quota_building >= 0),
 source_note text not null default '',
 unique (source_period, sort_order)
);
alter table public.manpower_analysis_rows enable row level security;
grant select, update on public.manpower_analysis_rows to authenticated;
drop policy if exists manpower_analysis_rows_sel on public.manpower_analysis_rows;
drop policy if exists manpower_analysis_rows_upd on public.manpower_analysis_rows;
create policy manpower_analysis_rows_sel on public.manpower_analysis_rows
 for select to authenticated using (my_role() <> 'none');
create policy manpower_analysis_rows_upd on public.manpower_analysis_rows
 for update to authenticated
 using (my_role() = 'admin' or (my_role() = 'unit_head' and (my_unit() = '*' or my_unit() = group_name or my_unit() = scope_unit or exists (select 1 from public.manpower_targets t where t.group_name = manpower_analysis_rows.group_name and t.unit_name = my_unit()))))
 with check (my_role() = 'admin' or (my_role() = 'unit_head' and (my_unit() = '*' or my_unit() = group_name or my_unit() = scope_unit or exists (select 1 from public.manpower_targets t where t.group_name = manpower_analysis_rows.group_name and t.unit_name = my_unit()))));
on conflict (source_period, sort_order) do nothing;
commit;

